class Solution {
public:
    int maxBoxesInWarehouse(vector<int>& boxes, vector<int>& warehouse) {
        sort(boxes.begin(), boxes.end());
        for (int i = 1; i < static_cast<int>(warehouse.size()); ++i) {
            warehouse[i] = min(warehouse[i], warehouse[i - 1]);
        }
        int box = 0;
        for (int room = static_cast<int>(warehouse.size()) - 1;
             room >= 0 && box < static_cast<int>(boxes.size()); --room) {
            if (boxes[box] <= warehouse[room]) {
                ++box;
            }
        }
        return box;
    }
};
